output_text:
[
  {
    "id": "no_carts_in_basket_only_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where customers must walk between opposing shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "basketOnlyAisle": {
          "or": [
            "singleFileAisle",
            "betweenOpposingShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "basketOnlyAisle"
        ]
      }
    }
  },
  {
    "id": "enter_basket_aisle_on_foot",
    "text": "A customer must not enter a single-file basket-only aisle while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "basketAisleEntrance": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "basketOnlyAisle": {
          "or": [
            "singleFileAisle",
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {
        "enterBasketOnlyAisleWithCart": {
          "pre": {
            "and": [
              "basketAisleEntrance",
              "hasCart",
              "N"
            ]
          },
          "post": "basketOnlyAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterBasketOnlyAisleWithCart"
    }
  },
  {
    "id": "cart_drop_only_at_aisle_mouths",
    "text": "Carts may be parked only at designated wide aisle mouths before entering the narrow shelf aisles.",
    "abstraction": {
      "state_properties": {
        "designatedCartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "designatedCartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart to enter a basket-only aisle, the customer is obliged to retrieve the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "designatedCartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartForBasketAisle": {
          "pre": {
            "and": [
              "designatedCartParkingMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartForBasketAisle",
      "discharge": "hasCart"
    }
  },
  {
    "id": "standard_shelf_service_requires_cart",
    "text": "Interactions with ordinary shelf faces in open aisles must be made while the customer has a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "basketOnlyAisle": {
          "or": [
            "singleFileAisle",
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "standardShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "basketOnlyAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "standardShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_roaming_except_service_zones",
    "text": "Customers should not roam without their cart except at the entrance cart area, designated cart-parking mouths, or inside basket-only aisles.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "basketOnlyAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "entranceCartArea",
            "cartParkingMouth",
            "basketOnlyAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "north_without_cart_only_for_basket_aisles",
    "text": "Moving north without a cart is allowed only when accessing or traversing a basket-only aisle.",
    "abstraction": {
      "state_properties": {
        "basketAisleEntrance": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "basketOnlyAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "cartlessNorthAllowedZone": {
          "or": [
            "basketAisleEntrance",
            "basketOnlyAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "N",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessNorthAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_cart_traffic_no_west",
    "text": "Cart traffic in open customer aisles follows a one-way eastbound circulation, so pushing a cart west is prohibited.",
    "abstraction": {
      "state_properties": {
        "openCustomerAisle": {
          "gt": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "hasCart",
          "openCustomerAisle"
        ]
      }
    }
  }
]
